mapper.select:
SELECT 
FROM workspaces w
JOIN workspace_memberships wm ON wm.workspace_id = w.id
WHERE wm.user_id = #{userId}
  AND w.id = #{id}
  AND w.deleted_at IS NULL

mapper.update:
UPDATE workspaces
SET deleted_at = #{deletedAt}, updated_at = #{deletedAt}
WHERE id = #{id} AND deleted_at IS NULL
